WITH flattened AS (SELECT id, service, log_ts, level, status_code, k, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS k, attr_value) SELECT level, DATE_TRUNC('DAY', log_ts) AS activity_day, k, MAX(log_ts) AS last_log_ts, BIT_OR(status_code) AS status_code_bit_or, COUNT_IF(k = 'version') AS version_events, COUNT(*) AS num_rows FROM flattened GROUP BY level, DATE_TRUNC('DAY', log_ts), k ORDER BY activity_day;
